<?php require __DIR__ . '/partials/drive-queue.php'; ?>
<div class="section-toolbar"><div class="tabs"><a href="<?= e(url('test-drives')) ?>" class="<?= empty($_GET['status']) ? 'active' : '' ?>">All requests</a><?php foreach (['Pending', 'Approved', 'Completed', 'Cancelled'] as $status): ?><a href="<?= e(url('test-drives', ['status' => $status])) ?>" class="<?= ($_GET['status'] ?? '') === $status ? 'active' : '' ?>"><?= e($status) ?></a><?php endforeach; ?></div><a class="button primary" href="<?= e(url('test-drive-new')) ?>">+ New request</a></div>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Request / Customer</th><th>Vehicle</th><th>Schedule (UTC+8)</th><th>Status</th><th class="align-right">Actions</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td class="strong">#<?= e($row['Test_Drive_ID']) ?> · <?= e($row['Customer_Name']) ?><small><?= e($row['Contact_Number']) ?></small></td><td><a class="text-link" href="<?= e(url('vehicle', ['id' => $row['Vehicle_ID']])) ?>"><?= e($row['Brand_Name'] . ' ' . $row['Model']) ?></a><small>Handled by <?= e($row['Employee_Name'] ?: '—') ?></small></td><td class="nowrap"><?= e(date('M j, Y', strtotime($row['Scheduled_Date']))) ?><small><?= e(date('g:i A', strtotime($row['Scheduled_Date']))) ?> · <?= e($row['Duration_Minutes']) ?> min</small></td><td><?= badge($row['Request_Status']) ?></td><td><div class="row-actions wrap-actions"><?php if (in_array($row['Request_Status'], ['Pending', 'Approved'], true)): ?><a href="<?= e(url('test-drive-edit', ['id' => $row['Test_Drive_ID']])) ?>">Reschedule</a><form method="post" action="<?= e(url('test-drive-status', ['id' => $row['Test_Drive_ID']])) ?>" data-confirm="Cancel this test-drive request? The record will be retained."><?= csrf() ?><input type="hidden" name="status" value="Cancelled"><button class="danger-text">Cancel</button></form><?php if ($row['Request_Status'] === 'Approved' && strtotime($row['Scheduled_Date']) + (int) $row['Duration_Minutes'] * 60 <= time()): ?><form method="post" action="<?= e(url('test-drive-status', ['id' => $row['Test_Drive_ID']])) ?>" data-confirm="Mark this test drive as completed?"><?= csrf() ?><input type="hidden" name="status" value="Completed"><button>Complete</button></form><?php endif; ?><?php else: ?><span class="muted">Recorded</span><?php endif; ?></div></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="5"><div class="empty-state"><span class="empty-icon" aria-hidden="true">◷</span><h3>No test-drive requests</h3><p>Record a request to reserve a vehicle and customer time slot.</p><a class="button primary" href="<?= e(url('test-drive-new')) ?>">+ New request</a></div></td></tr><?php endif; ?></tbody></table></div><?php $route = 'test-drives'; require __DIR__ . '/partials/pagination.php'; ?></section>
